X0,Y0,W,H=200,740,440,480
def load_uv(p):
    u=np.fromfile(p,np.float32).reshape(H,W,4)[::-1]
    full=np.zeros((1536,864,4),np.float32); full[Y0:Y0+H,X0:X0+W]=u
    return full
if __name__=='__main__':
    u=load_uv(sys.argv[1]); idm=np.rint(u[...,2]).astype(int); idm[np.abs(u[...,2]-idm)>0.01]=0
    P,a,m=approved_parts()
    G=dict(pom=idm==4,crown=idm==2,cuff=idm==3,star=idm==5,body=np.isin(idm,[1,6,7,8,9]))
    G['all']=idm>0
    P['all']=m
    print(f"{'part':6s} | {'approved bbox x0-x1, y0-y1 (w x h) centre':48s} | game")
    for k in ['all','pom','crown','cuff','star','body']:
        A=bbox(P[k]); B=bbox(G[k])
        f=lambda b: f"{b['x0']}-{b['x1']}, {b['y0']}-{b['y1']} ({b['w']}x{b['h']}) c({b['cx']},{b['cy']}) {b['px']}px"
        print(f"{k:6s} | {f(A):48s} | {f(B)}")
    # IoU of each part
    for k in ['pom','crown','cuff','star','body','all']:
        i=(P[k]&G[k]).sum(); un=(P[k]|G[k]).sum(); print(k,'IoU',round(i/un,3))
    cx=424
    def runs(lab):
        res=[];prev=None;s=0
        for y in range(760,1200):
            if lab[y]!=prev:
                if prev is not None: res.append(f'{prev}{s}-{y-1}')
                prev=lab[y]; s=y
        res.append(f'{prev}{s}-1199'); return ' '.join(res)
    names={0:'-',1:'B',2:'C',3:'U',4:'P',5:'S',6:'a',7:'a'}
    lab=[names.get(np.bincount(idm[y,cx-5:cx+6],minlength=11).argmax(),'?') for y in range(1536)]
    print('GAME centre', runs(lab))
    pl=np.zeros((1536,864),int)
    for i,k in enumerate(['body','cuff','crown','pom','star'],1): pl[P[k]]=i
    nm={0:'-',1:'B',2:'U',3:'C',4:'P',5:'S'}
    lab=[nm[np.bincount(pl[y,cx-5:cx+6],minlength=6).argmax()] for y in range(1536)]
    print('APPR centre', runs(lab))
    for y in range(780,1195,15):
        ra=np.nonzero(m[y])[0]; rg=np.nonzero(G['all'][y])[0]
        f=lambda r: f'{r.min()}-{r.max()} w{r.max()-r.min()+1}' if len(r) else '-'
        print(y,'APP',f(ra),' GAME',f(rg))

"""Benny part segmentation helpers (benny-character-artist, Screen 05 full reference match).
approved_parts(): colour classes inside masks/benny_and_hat.png of the APPROVED picture ->
  pom / crown white bands / crown purple band / cuff / star / body / arm nubs (boolean masks).
game_parts(mask_capture, hide_capture): the same parts in the REAL game from a `?bennyMask=1` flat-ID capture
  (pixels that differ from the `hide=benny` capture, classified by ID colour).
"""
import numpy as np
from PIL import Image
from scipy import ndimage as ndi

REF = "references/05_flow_into_the_current.png"
MASK = "qa/pilot05/full_reference_match/masks/benny_and_hat.png"


def rgb2hsv(a):
    a = a / 255.0
    mx, mn = a.max(-1), a.min(-1)
    d = mx - mn
    h = np.zeros(mx.shape)
    r, g, b = a[..., 0], a[..., 1], a[..., 2]
    nz = d > 1e-9
    i = nz & (mx == r); h[i] = ((g - b)[i] / d[i]) % 6
    i = nz & (mx == g) & (mx != r); h[i] = (b - r)[i] / d[i] + 2
    i = nz & (mx == b) & (mx != r) & (mx != g); h[i] = (r - g)[i] / d[i] + 4
    s = np.where(mx > 0, d / np.maximum(mx, 1e-9), 0)
    return h * 60, s, mx


def load(p):
    return np.asarray(Image.open(p).convert("RGB")).astype(float)


def colour_classes(a):
    """1 pink, 2 purple, 3 white, 4 yellow, 0 other"""
    H, S, V = rgb2hsv(a)
    cls = np.zeros(a.shape[:2], np.uint8)
    cls[((H > 297) | (H < 10)) & (S > 0.25)] = 1
    cls[(H > 240) & (H <= 297) & (S > 0.3)] = 2
    cls[(S <= 0.3) & (V > 0.55)] = 3
    cls[(H > 28) & (H < 65) & (S > 0.45) & (V > 0.6)] = 4
    return cls


def bbox(m):
    ys, xs = np.nonzero(m)
    if not len(xs):
        return None
    return dict(x0=int(xs.min()), x1=int(xs.max()), y0=int(ys.min()), y1=int(ys.max()), w=int(xs.max() - xs.min() + 1),
                h=int(ys.max() - ys.min() + 1), cx=round(float(xs.mean()), 1), cy=round(float(ys.mean()), 1), px=int(m.sum()))


def biggest(m, n=1):
    lab, k = ndi.label(m)
    if k == 0:
        return m
    sz = ndi.sum(m, lab, range(1, k + 1))
    keep = np.argsort(sz)[::-1][:n] + 1
    return np.isin(lab, keep)
